CustomField.formula:
IF(Total_CTC__c < 1000, TEXT(Total_CTC__c),
  IF(Total_CTC__c < 1000000, TEXT(FLOOR(Total_CTC__c/1000)) & ',' & RIGHT(TEXT(Total_CTC__c), 3),
    IF(Total_CTC__c < 1000000000, TEXT(FLOOR(Total_CTC__c/1000000)) & ',' & TEXT(FLOOR(MOD(Total_CTC__c,1000000)/1000)) & ',' & RIGHT(TEXT(Total_CTC__c), 3), "Error:Number Greater Than 999,999,999")
  )
)
